// Maps an order onto the fields the invoice-classic template expects.
// Change the vendor details and tax rate to your own.
const order = $json;
const taxRate = 0.1;

const money = (amount) =>
	amount.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const formatDate = (date) =>
	date.toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });

const issued = new Date(order.date);
const due = new Date(issued);
due.setDate(due.getDate() + 30);

const subtotal = order.items.reduce((sum, item) => sum + item.qty * item.unitPrice, 0);
const tax = Math.round(subtotal * taxRate * 100) / 100;
const total = subtotal + tax;
const invoiceNumber = `INV-${order.orderNumber}`;

return {
	json: {
		invoiceNumber,
		poNumber: order.orderNumber,
		date: formatDate(issued),
		dueDate: formatDate(due),
		paymentTerms: 'Net 30',
		currency: 'USD',
		vendor: {
			name: 'Example Supplies Inc.',
			address: '500 Innovation Drive\nSan Jose, CA 95110\nUnited States',
			phone: '(408) 555-0142',
			email: 'billing@example.com',
			website: 'example.com',
			taxId: 'EIN 00-0000000',
		},
		customer: order.customer,
		items: order.items.map((item) => ({
			description: item.description,
			qty: item.qty,
			unit: item.unit,
			unitPrice: money(item.unitPrice),
			total: money(item.qty * item.unitPrice),
		})),
		subtotal: money(subtotal),
		discountLabel: 'Discount',
		discountAmount: money(0),
		taxableAmount: money(subtotal),
		taxLabel: `Sales tax (${taxRate * 100}%)`,
		taxAmount: money(tax),
		total: money(total),
		amountPaid: money(0),
		balanceDue: money(total),
		notes: `Please quote ${invoiceNumber} with your payment.`,
		paymentInstructions: 'Bank transfer: Example Bank, routing 000000000, account 0000-000-000',
		payment: { url: `https://example.com/pay/${invoiceNumber}` },
	},
};
